import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

public class Ex05HashVsDollar {

    static class Bound {
        String sql;
        final List<String> params = new ArrayList<String>();
    }

    // #{} -> ? 占位符，值进入参数列表（预编译路径）
    static Bound hashBind(String sql, Map<String, String> ctx) {
        Bound b = new Bound();
        Matcher m = Pattern.compile("#\\{([^}]+)\\}").matcher(sql);
        StringBuffer sb = new StringBuffer();
        while (m.find()) {
            String v = ctx.get(m.group(1));
            b.params.add(v == null ? "null" : v);
            m.appendReplacement(sb, "?");
        }
        m.appendTail(sb);
        b.sql = sb.toString();
        return b;
    }

    // ${} -> 文本插值（字符串拼接路径）
    static String dollarInline(String sql, Map<String, String> ctx) {
        Matcher m = Pattern.compile("\\$\\{([^}]+)\\}").matcher(sql);
        StringBuffer sb = new StringBuffer();
        while (m.find()) {
            String v = ctx.get(m.group(1));
            if (v == null) {
                v = "${" + m.group(1) + "}";
            }
            m.appendReplacement(sb, Matcher.quoteReplacement(v));
        }
        m.appendTail(sb);
        return sb.toString();
    }

    static List<Map<String, String>> table() {
        String[] names = { "tom", "amy", "bob" };
        List<Map<String, String>> rows = new ArrayList<Map<String, String>>();
        for (int i = 0; i < names.length; i++) {
            Map<String, String> r = new LinkedHashMap<String, String>();
            r.put("id", String.valueOf(i + 1));
            r.put("name", names[i]);
            rows.add(r);
        }
        return rows;
    }

    static String token(String tok, Map<String, String> row) {
        if (tok.length() >= 2 && tok.startsWith("'") && tok.endsWith("'")) {
            return tok.substring(1, tok.length() - 1);
        }
        String v = row.get(tok);
        return v == null ? "" : v;
    }

    // 极简 WHERE 求值器：支持 OR / AND 两级，项形如 a = b
    static boolean evalWhere(String expr, Map<String, String> row) {
        for (String orPart : expr.split("(?i)\\s+OR\\s+")) {
            boolean all = true;
            for (String andPart : orPart.split("(?i)\\s+AND\\s+")) {
                String[] kv = andPart.trim().split("\\s*=\\s*", 2);
                if (kv.length != 2) {
                    all = false;
                    break;
                }
                if (!token(kv[0].trim(), row).equals(token(kv[1].trim(), row))) {
                    all = false;
                    break;
                }
            }
            if (all) {
                return true;
            }
        }
        return false;
    }

    public static void main(String[] args) {
        String attack = "' OR '1'='1";
        Map<String, String> ctx = new LinkedHashMap<String, String>();
        ctx.put("name", attack);
        List<Map<String, String>> rows = table();

        Bound hb = hashBind("SELECT * FROM t_user WHERE name = #{name}", ctx);
        int hMatched = 0;
        for (Map<String, String> r : rows) {
            if (r.get("name").equals(hb.params.get(0))) {
                hMatched++;
            }
        }
        System.out.println("table rows         : " + rows.size());
        System.out.println("hash sql           : " + hb.sql);
        System.out.println("hash params        : " + hb.params);
        System.out.println("hash rows matched  : " + hMatched);

        String ds = dollarInline("SELECT * FROM t_user WHERE name = '${name}'", ctx);
        String where = ds.substring(ds.indexOf("WHERE ") + 6);
        int dMatched = 0;
        for (Map<String, String> r : rows) {
            if (evalWhere(where, r)) {
                dMatched++;
            }
        }
        System.out.println("dollar sql         : " + ds);
        System.out.println("dollar where       : " + where);
        System.out.println("dollar rows matched: " + dMatched);
        System.out.println("hash injected      : " + (hMatched == rows.size()));
        System.out.println("dollar injected    : " + (dMatched == rows.size()));

        Map<String, String> ord = new LinkedHashMap<String, String>();
        ord.put("column", "age DESC");
        System.out.println("order by allow     : SELECT * FROM t_user ORDER BY "
                + dollarInline("${column}", ord));

        String[] white = { "age", "name", "create_time" };
        String badValue = "age; DROP TABLE t_user";
        boolean accepted = false;
        for (String w : white) {
            if (w.equals(badValue)) {
                accepted = true;
            }
        }
        System.out.println("order by deny      : accepted=" + accepted + " value=" + badValue);
    }
}
